 static int checks;static void check(boolean b,String s){if(!b)throw new AssertionError(s);checks++;System.out.println("PASS "+s);}static final class Results implements UdpVideoProtocol.Sink{final List<byte[]> frames=new ArrayList<>();int losses;public void frame(byte[] b){frames.add(b);}public void loss(){losses++;}}
